head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.btnValue_onclick = function(e) {
    // Node instance data에 없는 값으로 찾음
    trv1.findNodeByValue("1", true);
};
scwin.btnIndex_onclick = function(e) {
    // Node instance data에 없는 index로 찾음
    trv1.findNodeByIndex(99, true);
};
scwin.btnLog_onclick = function(e) {
    WebSquare.logger.showLog();
};
scwin.__checkErr = function() {
    return temp = WebSquare.logger.getErrorLog();
}
scwin.checkVal1 = function() {
    return window.getComputedStyle(scwin.__getDom($p.id + 'trv1_label_1')).getPropertyValue('color') == 'rgb(56, 61, 65)';
}
scwin.checkVal2 = function() {
    return window.getComputedStyle(scwin.__getDom($p.id + 'trv1_label_1')).getPropertyValue('color') == 'rgb(56, 61, 65)';
}
